// Parse and validate Gemini response
try {
  const geminiResponse = $input.first().json.response;

  // Try to extract JSON from the response
  let extractedData;

  if (typeof geminiResponse === 'string') {
    // Remove any markdown code blocks or extra text
    const jsonMatch = geminiResponse.match(/```json\s*([\s\S]*?)\s*```/) || 
                     geminiResponse.match(/\{[\s\S]*\}/);

    if (jsonMatch) {
      extractedData = JSON.parse(jsonMatch[1] || jsonMatch[0]);
    } else {
      throw new Error('No valid JSON found in response');
    }
  } else {
    extractedData = geminiResponse;
  }

  // Validate required structure
  const validatedData = {
    claimNumber: extractedData.claimNumber || null,
    claimantName: extractedData.claimantName || null,
    claimantId: extractedData.claimantId || null,
    dateOfIncident: extractedData.dateOfIncident || null,
    incidentDescription: extractedData.incidentDescription || null,
    claimAmount: extractedData.claimAmount ? Number(extractedData.claimAmount) : null,
    currency: extractedData.currency || null,
    policyNumber: extractedData.policyNumber || null,
    contactInfo: {
      email: extractedData.contactInfo?.email || null,
      phone: extractedData.contactInfo?.phone || null,
      address: extractedData.contactInfo?.address || null
    },
    medicalInfo: {
      doctorName: extractedData.medicalInfo?.doctorName || null,
      hospitalName: extractedData.medicalInfo?.hospitalName || null,
      diagnosis: extractedData.medicalInfo?.diagnosis || null,
      treatmentDate: extractedData.medicalInfo?.treatmentDate || null
    },
    vehicleInfo: {
      make: extractedData.vehicleInfo?.make || null,
      model: extractedData.vehicleInfo?.model || null,
      year: extractedData.vehicleInfo?.year ? Number(extractedData.vehicleInfo.year) : null,
      licensePlate: extractedData.vehicleInfo?.licensePlate || null,
      damageDescription: extractedData.vehicleInfo?.damageDescription || null
    },
    additionalDetails: extractedData.additionalDetails || {},
    confidence: extractedData.confidence || 0.5
  };

  return {
    success: true,
    extractedData: validatedData,
    confidence: validatedData.confidence,
    processedAt: new Date().toISOString(),
    documentId: $('Webhook Trigger').first().json.body.documentId
  };

} catch (error) {
  return {
    success: false,
    error: `Data processing failed: ${error.message}`,
    processedAt: new Date().toISOString(),
    documentId: $('Webhook Trigger').first().json.body.documentId
  };
}

// Process final claim submission
const claimData = $input.first().json.body;

// Generate a unique claim ID
const claimId = `CLM-${Date.now()}-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;

// Structure the final claim submission
const finalClaim = {
  claimId: claimId,
  submissionDate: new Date().toISOString(),
  status: 'submitted',
  documents: claimData.documents || [],
  extractedData: claimData.extractedData || {},
  userVerified: claimData.userVerified || false,
  processingNotes: {
    submittedVia: 'web-portal',
    aiProcessed: true,
    documentsCount: (claimData.documents || []).length,
    averageConfidence: claimData.extractedData?.confidence || 0
  }
};

// Log the submission (in production, this would go to your database/API)
console.log('New claim submitted:', finalClaim);

return {
  success: true,
  claimId: claimId,
  message: 'Claim submitted successfully',
  submittedAt: finalClaim.submissionDate
};
